head.script:
scwin.inputCalendar1_onviewchange = function(info) { //debugger;
    console.log(info.oldValue + "	" + info.newValue);
};
scwin.inputCalendar1_onyearselect = function(info) {};
scwin.__lostFocus = function() {
    WebSquare.wUnit.getJq('input').blur();
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getObjById('inputCalendar1_input').value == checkYear;
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getObjById('inputCalendar2_input').value == checkYearMonth;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 0. inputCalendar 속성을 확인한다.
    //0. Check the inputCalendar property.
    //Verify step 0. renderType='native'
    //0. renderType = 'native'
    //Test step 1. 샘플파일 실행 후 첫번째 캘린더아이콘을 클릭하여 연도값을 변경하고 'v'버튼을 클릭한다.
    //1. After running the sample file, click the first calendar icon to change the year value and click the 'v' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar1_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_next_year_yearType')[0].click()");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_btn_ok_yearType')[0].click()");
    //Verify step 1. 변경된 연도값이 입력창에 보여진다.
    //1. The changed year value is displayed in the input window.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    //Test step 2. 첫번째 캘린더아이콘을 클릭하여 연도값을 변경하고 'x'버튼을 클릭한다.
    //2. Click the first calendar icon to change the year value and click the 'x' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar1_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_next_year_yearType')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_btn_close_yearType')[0].click()");
    //Verify step 2. 변경된 연도값이 입력창에 보여지지 않는다.
    //2. The changed year value is not shown in the input window.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    //Test step 3. 두번째 캘런더(calendarValueType='yearMonth') 아이콘의 연도값을 변경하고 위의 1번과 2번을 수행한다.
    //3. Change the year value of the second calendar (calendarValueType = 'yearMonth') icon and perform steps 1 and 2 above.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_last_month')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_next_month')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_next_year')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_btn_ok')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.__lostFocus()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 3. 위의 1번내용과 2번내용이 수행되어진다.
    //3. Contents 1 and 2 are performed.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    //Test step 3. 두번째 캘런더(calendarValueType='yearMonth') 아이콘의 연도값을 변경하고 위의 1번과 2번을 수행한다.
    //3. Change the year value of the second calendar (calendarValueType = 'yearMonth') icon and perform steps 1 and 2 above.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_last_month')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_next_month')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_next_year')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_btn_close')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.__lostFocus()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 3. 위의 1번내용과 2번내용이 수행되어진다.
    //3. Contents 1 and 2 are performed.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 12-Feb-2018
    window.currentTime = new Date();
    window.checkYear = currentTime.getFullYear() + 1;
    //var checkMonth = sprintf("%02d", currentTime.getMonth());
    window.checkMonth = currentTime.getMonth() + 1;
    window.checkYearMonth = "";
    if (checkMonth < 10) {
        checkYearMonth = String(checkYear) + "-" + "0" + String(checkMonth);
    } else {
        checkYearMonth = String(checkYear) + "-" + String(checkMonth);
    }
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
